import sqlite3
import subprocess
from contextlib import closing
from datetime import datetime, timezone
from langchain_core.tools import tool
DB_PATH = 'listings.db'

def _refresh_feeds(mls_number: str) -> None:
    # Trigger the syndication job so portals pick up the new price
    subprocess.run(['./scripts/syndicate_listing.sh', mls_number], check=False, timeout=60)

@tool
def update_listing_price(mls_number: str, new_price: float, reason: str='') -> dict:
    if new_price <= 0:
        return {'error': 'new_price must be positive'}
    mls_number = mls_number.strip().upper()
    now = datetime.now(timezone.utc).isoformat()
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute('SELECT price, status FROM listings WHERE mls_number = ?', (mls_number,))
            row = cur.fetchone()
            if row is None:
                return {'error': f'no listing found for {mls_number}'}
            old_price, status = row
            if status in ('sold', 'withdrawn'):
                return {'error': f'cannot change price of a {status} listing'}
            if old_price == new_price:
                return {'mls_number': mls_number, 'changed': False, 'price': old_price}
            conn.execute('UPDATE listings SET price = ?, updated_at = ? WHERE mls_number = ?', (new_price, now, mls_number))
            conn.execute('INSERT INTO price_history (mls_number, old_price, new_price, reason, changed_at) VALUES (?, ?, ?, ?, ?)', (mls_number, old_price, new_price, reason, now))
    _refresh_feeds(mls_number)
    pct = round((new_price - old_price) / old_price * 100, 2)
    return {'mls_number': mls_number, 'changed': True, 'old_price': old_price, 'new_price': new_price, 'percent_change': pct}
